1	const express = require('express');
2	const router = express.Router();
3	const { readLimiter } = require('../middlewares/rateLimit');
4	router.use(readLimiter); // route-wide rate limiting (trusted AI service calls are skipped)
5	const { IncidentLog, DetectionAlert, sequelize } = require('../models');
6	const { Op } = require("sequelize");
7	const axios = require('axios');
8	const multer = require('multer');
