11	const { aiServiceHeaders } = require('../services/aiServiceAuth');
12	require('dotenv').config();
13	
14	const ALLOWED_STATUSES = ['Active', 'Investigating', 'Escalated to Security', 'Cleared'];
15	const SEVERITIES = ['Low', 'Medium', 'High', 'Critical'];
16	
17	// Mirrors detectionAlerts.js's STATUS_TO_RESOLUTION in reverse — only values both
18	// IncidentLog.resolutionStatus and DetectionAlert.status already support.
19	const RESOLUTION_TO_ALERT_STATUS = {
20	    Active: 'Active',
21	    Investigating: 'Investigating',
22	    'Escalated to Security': 'Escalated',
23	    Cleared: 'Cleared'
24	};
25	
26	// Runs fn inside a managed transaction when the connection is available; unit tests that
27	// mock ../models without a sequelize instance fall back to running fn untransacted.
28	const withTransaction = (fn) => {
29	    if (sequelize && typeof sequelize.transaction === 'function') {
30	        return sequelize.transaction(fn);
31	    }
32	    return fn(null);
33	};
34	
35	// Finds the DetectionAlert linked to this incident (the inverse of
36	// detectionAlerts.js's findLinkedIncident). Returns null (never throws) for incidents
37	// that predate the link, or when ../models is mocked without DetectionAlert.
38	async function findLinkedAlert(log, t) {
39	    if (!DetectionAlert || typeof DetectionAlert.findOne !== 'function') return null;
40	    try {
41	        return await DetectionAlert.findOne({
42	            where: { incident_log_id: log.id },
43	            ...(t ? { transaction: t } : {})
44	        });
45	    } catch {
46	        return null;
47	    }
48	}
49	
50	// Incoming frames stay in memory only long enough to proxy them to the AI
51	// service. Bound both type and size before allocating/forwarding the payload.
52	const MAX_FRAME_BYTES = 8 * 1024 * 1024;
53	const ALLOWED_FRAME_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);
54	const upload = multer({
55	    storage: multer.memoryStorage(),
56	    limits: { fileSize: MAX_FRAME_BYTES, files: 1 },
57	    fileFilter: (_req, file, callback) => {
58	        if (ALLOWED_FRAME_TYPES.has(file.mimetype)) return callback(null, true);
59	        const error = new Error('Unsupported image type.');
60	        error.code = 'UNSUPPORTED_IMAGE_TYPE';
61	        return callback(error);
62	    }
63	});
64	
65	const acceptFrameUpload = (req, res, next) => {
66	    upload.single('file')(req, res, (error) => {
67	        if (!error) return next();
68	        if (error.code === 'LIMIT_FILE_SIZE') {
69	            return res.status(413).json({ error: 'Image frame exceeds the 8 MB limit.' });
70	        }
71	        if (error.code === 'UNSUPPORTED_IMAGE_TYPE') {
72	            return res.status(415).json({ error: 'Image frame must be JPEG, PNG, or WebP.' });
73	        }
74	        return res.status(400).json({ error: 'Invalid image frame upload.' });
75	    });
76	};
77	
78	// -------------------------------------------------------------
79	// AI INTEGRATION ROUTE: Scan frame and save to DB automatically
80	// -------------------------------------------------------------
81	// Camera bridge posts frames server-to-server with the shared AI service key;
82	// FM/Staff JWTs may also call it for manual testing. Never publicly accessible.
83	router.post("/scan-frame", verifyServiceOrRole('FM', 'Staff'), acceptFrameUpload, async (req, res) => {
84	    const cameraLocation = req.body.camera_location || "Unknown Sector";
85	
86	    if (!req.file) {
87	        return res.status(400).json({ error: "No image frame provided" });
88	    }
89	
90	    if (!process.env.PYTHON_AI_URL) {
91	        return res.status(503).json({ error: "AI service is not configured (PYTHON_AI_URL missing)." });
92	    }
93	
94	    try {
95	        // 1. Package the frame for Python
96	        const formData = new FormData();
97	        formData.append('file', req.file.buffer, req.file.originalname);
98	
99	        // 2. Request AI analysis
100	        // Merge multipart headers with the AI-service auth headers (Google ID
101	        // token on Cloud Run + X-AI-Service-Key defence in depth).
102	        const aiResponse = await axios.post(process.env.PYTHON_AI_URL, formData, {
103	            headers: {
104	                ...formData.getHeaders(),
105	                ...(await aiServiceHeaders(process.env.PYTHON_AI_URL))
106	            }
107	        });
108	
109	        const faces = aiResponse.data.faces;
110	        const savedLogs = [];
111	
112	        // 3. Save AI results into PostgreSQL via Sequelize
113	        for (let face of faces) {
114	            let newLog = await IncidentLog.create({
115	                camera_location: cameraLocation,
116	                status: face.status,
117	                person_name: face.name,
118	                confidence_score: face.confidence
119	            });
120	            savedLogs.push(newLog);
121	
122	            if (face.status === "UNAUTHORIZED_ACCESS") {
123	                console.log(`🚨 ALERT: Unauthorized access (${face.name}) at ${cameraLocation}!`);
124	            } else {
125	                console.log(`✅ LOGGED: ${face.name} authorized at ${cameraLocation}.`);
126	            }
127	        }
128	
129	        res.json({ success: true, ai_detections: faces, db_logs: savedLogs });
130	
131	    } catch (err) {
132	        console.error("AI Communication Error:", err.message);
133	        res.status(500).json({ error: "Failed to process frame with AI Service" });
134	    }
135	});
136	
137	// -------------------------------------------------------------
138	// Manual FM incident creation
139	// -------------------------------------------------------------
140	router.post("/", verifyToken, requireRole('FM'), async (req, res) => {
141	    const { camera_location, status, source, severity, person_name, confidence_score, notes } = req.body;
142	    if (!camera_location || !status || !source || !severity) {
143	        return res.status(400).json({ error: "camera_location, status, source, and severity are required." });
144	    }
145	    try {
146	        const log = await IncidentLog.create({
147	            camera_location,
148	            status,
149	            source,
150	            severity,
151	            person_name: person_name || null,
152	            confidence_score: confidence_score ? parseFloat(confidence_score) : null,
153	            notes: notes || '',
154	            resolutionStatus: 'Active'
155	        });
156	        res.status(201).json(log);
157	    } catch (err) {
158	        console.error("Failed to create incident:", err);
159	        res.status(500).json({ error: "Failed to create incident log." });
160	    }
161	});
162	
163	// -------------------------------------------------------------
164	// STANDARD CRUD: Get all logs for React Dashboard
165	// -------------------------------------------------------------
166	router.get("/", verifyToken, requireRole('FM'), async (req, res) => {
167	    let condition = {};
168	    let search = req.query.search;
169	
170	    // Allow React frontend to search by name or location
171	    if (search) {
172	        condition[Op.or] = [
173	            { person_name: { [Op.like]: `%${search}%` } },
174	            { camera_location: { [Op.like]: `%${search}%` } },
175	            { status: { [Op.like]: `%${search}%` } }
176	        ];
177	    }
178	
179	    try {
180	        let list = await IncidentLog.findAll({
181	            where: condition,
182	            order: [['createdAt', 'DESC']]
183	        });
184	        res.json(list);
185	    } catch (err) {
186	        console.error("Failed to fetch incident logs:", err);
187	        res.status(500).json({ error: "Failed to fetch incident logs." });
188	    }
189	});
190	
191	// Get specific log
192	router.get("/:id", verifyToken, requireRole('FM'), async (req, res) => {
193	    let id = req.params.id;
194	    try {
195	        let log = await IncidentLog.findByPk(id);
196	        if (!log) {
197	            res.sendStatus(404);
198	            return;
199	        }
200	        res.json(log);
201	    } catch (err) {
202	        console.error("Failed to fetch incident log:", err);
203	        res.status(500).json({ error: "Failed to fetch incident log." });
204	    }
205	});
