### 3.2 New file `client/src/pages/IncidentAnalytics.jsx` — skeleton
```jsx
import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router';
import axios from 'axios';
import Sidebar from '../components/Sidebar';
import '../css/Dashboard.css';
import '../css/IncidentDashboard.css'; // reuse .sr-only, badge tones if needed
import '../css/IncidentAnalytics.css';
import {
  computeMTTR,
  computeAIAccuracy,
  computeConfidenceBuckets,
  computeResolutionFunnel,
} from '../utils/incidentAnalytics';

const IncidentAnalytics = () => {
  const navigate = useNavigate();
  const [incidents, setIncidents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [unavailable, setUnavailable] = useState(false);

  const getToken = () => localStorage.getItem('accessToken');

  const fetchIncidents = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get('/api/incident', { headers: { Authorization: `Bearer ${getToken()}` } });
      setIncidents(Array.isArray(res.data) ? res.data : []);
      setUnavailable(false);
    } catch (err) {
      console.error('Failed to fetch incidents for analytics:', err);
      setUnavailable(true);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchIncidents(); }, [fetchIncidents]);

  const mttr = computeMTTR(incidents);
  const accuracy = computeAIAccuracy(incidents);
  const buckets = computeConfidenceBuckets(incidents);
  const funnel = computeResolutionFunnel(incidents);

  return (
    <div className="dashboard-layout">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div className="header-titles">
            <h1>Incident Deep Analytics</h1>
            <p style={{ color: '#94a3b8', marginTop: '4px' }}>Resolution performance and AI accuracy — last 7 days where noted</p>
          </div>
          <div className="inc-header-actions">
            <button type="button" className="edit-btn" onClick={() => navigate('/incidents')}>← Back to Incident Dashboard</button>
            <button className="dashboard-refresh-btn" onClick={fetchIncidents} disabled={loading}>{loading ? 'Refreshing…' : 'Refresh'}</button>
          </div>
        </header>

        {unavailable && <p className="analytics-empty analytics-unavailable" role="status">Analytics temporarily unavailable. Retrying…</p>}

        {/* KPI row */}
        <section className="ia-kpi-row">
          <MTTRStatTile mttr={mttr} />
          <AccuracyMeter accuracy={accuracy} />
        </section>

        <ConfidenceBucketChart buckets={buckets} />
        <ResolutionFunnelChart funnel={funnel} />
      </main>
    </div>
  );
};
export default IncidentAnalytics;
```
Sub-components (`MTTRStatTile`, `AccuracyMeter`, `ConfidenceBucketChart`, `ResolutionFunnelChart`) can live inline in this same file (this page is not huge) or as separate files under `client/src/components/` (`MTTRStatTile.jsx`, `AccuracyMeter.jsx`, `ConfidenceBucketChart.jsx`, `ResolutionFunnelChart.jsx`) mirroring the `AlertTrendChart.jsx`/`TopAlertZonesChart.jsx` precedent of one chart per file. **Recommend the separate-files approach** since it matches the existing convention exactly and keeps each accessible-chart's `role="img"`/`aria-label`/`sr-only table` self-contained and independently testable.

### 3.3 The four sub-components — exact shape

**a) `MTTRStatTile` (Item 1)** — stat-tile contract per skill: `label` + `value` (auto-compact) + `trend` (sparkline, de-emphasis gray, current period in accent).
```jsx
const MTTRStatTile = ({ mttr }) => (
  <div className="ia-stat-tile">
    <div className="ia-stat-label">Avg. Resolution Time</div>
    <div className="ia-stat-value">{mttr.avgLabel}</div>
    <div className="ia-sparkline" role="img" aria-label={`Average resolution time trend over the last 7 days: ${mttr.trend.map(t => t.label).join(', ')}`}>
      {mttr.trend.map((t, i) => (
        <div
          key={t.date}
          className={`ia-sparkline-bar${i === mttr.trend.length - 1 ? ' ia-sparkline-bar-current' : ''}`}
          style={{ height: `${mttr.trend.max ? (t.avgMs / mttr.trend.max) * 100 : 0}%` }}
          title={`${t.label}: ${t.avgLabel}`}
        />
      ))}
    </div>
    <table className="sr-only"><caption>Average resolution time per day (last 7 days)</caption>
      <thead><tr><th scope="col">Day</th><th scope="col">Avg. resolution time</th></tr></thead>
      <tbody>{mttr.trend.map(t => <tr key={t.date}><th scope="row">{t.label}</th><td>{t.avgLabel}</td></tr>)}</tbody>
    </table>
  </div>
);
```
Single-series sparkline needs **no legend box** (per mark-spec rule: one color, the tile's own label already names it).

**b) `AccuracyMeter` (Item 2a)**
```jsx
const AccuracyMeter = ({ accuracy }) => (
  <div className="ia-stat-tile">
    <div className="ia-stat-label">AI Accuracy Rate</div>
    <div className="ia-stat-value">{accuracy.evaluatedCount > 0 ? `${accuracy.accuracyPct.toFixed(1)}%` : '—'}</div>
    <div
      className="ia-meter"
      role="img"
      aria-label={`AI accuracy rate: ${accuracy.accuracyPct.toFixed(1)} percent, based on ${accuracy.evaluatedCount} evaluated AI incidents`}
    >
      <div className={`ia-meter-fill ia-meter-fill-${accuracy.tier}`} style={{ width: `${accuracy.accuracyPct}%` }} />
    </div>
    <div className="ia-stat-sublabel">{accuracy.evaluatedCount} evaluated AI incidents ({accuracy.falsePositiveCount} false positive)</div>
  </div>
);
```
Tiers: `accent` (`#3b82f6`, ≥90%), `warning` (`#f59e0b`, 70–89%), `danger` (`#ef4444`, <70%) — reusing the app's own already-established accent/warning/danger vocabulary (same hues as `.inc-stat-blue`, `.dashboard-stale-banner`, `.trend-bar-critical`) rather than inventing a new triplet, since a meter shows one tier at a time (no simultaneous-adjacency CVD concern the way a categorical legend has). Track = a lighter step of blue (`#2d364f`, matching the existing card-border tone) per the "unfilled track is a lighter step of the same ramp" mark spec.

**c) `ConfidenceBucketChart` (Item 2b)** — stacked horizontal bar per bucket, status-paired (not categorical):
```jsx
const BUCKET_ORDER = ['90–100%', '70–89%', 'Below 70%'];
const ConfidenceBucketChart = ({ buckets }) => (
  <section className="analytics-panel" aria-labelledby="confidence-bucket-heading">
    <div className="analytics-panel-head">
      <h3 id="confidence-bucket-heading">AI Confidence vs. Outcome</h3>
      <div className="analytics-legend" aria-hidden="true">
        <span className="legend-item"><span className="legend-swatch ia-legend-valid" /> ✓ Valid</span>
        <span className="legend-item"><span className="legend-swatch ia-legend-fp" /> ✕ False Positive</span>
      </div>
    </div>
    <ul className="zones-list">
      {buckets.map(b => {
        const total = b.valid + b.falsePositive || 1;
        return (
          <li className="zone-row ia-confidence-row" key={b.bucket}>
            <span className="zone-name">{b.bucket}</span>
            <span className="zone-bar-track ia-confidence-track" aria-hidden="true">
              <span className="ia-confidence-segment ia-confidence-valid" style={{ width: `${(b.valid / total) * 100}%` }} title={`Valid: ${b.valid}`} />
              <span className="ia-confidence-segment ia-confidence-fp" style={{ width: `${(b.falsePositive / total) * 100}%` }} title={`False Positive: ${b.falsePositive}`} />
            </span>
            <span className="zone-count" aria-label={`${b.bucket}: ${b.valid} valid, ${b.falsePositive} false positive`}>{b.valid + b.falsePositive}</span>
