### 3.2 New file `client/src/pages/IncidentAnalytics.jsx` — skeleton
```jsx
import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router';
import axios from 'axios';
import Sidebar from '../components/Sidebar';
import '../css/Dashboard.css';
import '../css/IncidentDashboard.css'; // reuse .sr-only, badge tones if needed
import '../css/IncidentAnalytics.css';
import {
  computeMTTR,
  computeAIAccuracy,
  computeConfidenceBuckets,
  computeResolutionFunnel,
} from '../utils/incidentAnalytics';

const IncidentAnalytics = () => {
  const navigate = useNavigate();
  const [incidents, setIncidents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [unavailable, setUnavailable] = useState(false);

  const getToken = () => localStorage.getItem('accessToken');

  const fetchIncidents = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get('/api/incident', { headers: { Authorization: `Bearer ${getToken()}` } });
      setIncidents(Array.isArray(res.data) ? res.data : []);
      setUnavailable(false);
    } catch (err) {
      console.error('Failed to fetch incidents for analytics:', err);
      setUnavailable(true);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchIncidents(); }, [fetchIncidents]);

  const mttr = computeMTTR(incidents);
  const accuracy = computeAIAccuracy(incidents);
  const buckets = computeConfidenceBuckets(incidents);
  const funnel = computeResolutionFunnel(incidents);

  return (
    <div className="dashboard-layout">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div className="header-titles">
            <h1>Incident Deep Analytics</h1>
            <p style={{ color: '#94a3b8', marginTop: '4px' }}>Resolution performance and AI accuracy — last 7 days where noted</p>
          </div>
          <div className="inc-header-actions">
            <button type="button" className="edit-btn" onClick={() => navigate('/incidents')}>← Back to Incident Dashboard</button>
            <button className="dashboard-refresh-btn" onClick={fetchIncidents} disabled={loading}>{loading ? 'Refreshing…' : 'Refresh'}</button>
          </div>
        </header>

        {unavailable && <p className="analytics-empty analytics-unavailable" role="status">Analytics temporarily unavailable. Retrying…</p>}

        {/* KPI row */}
        <section className="ia-kpi-row">
          <MTTRStatTile mttr={mttr} />
          <AccuracyMeter accuracy={accuracy} />
        </section>

        <ConfidenceBucketChart buckets={buckets} />
        <ResolutionFunnelChart funnel={funnel} />
      </main>
    </div>
  );
};
export default IncidentAnalytics;
```
Sub-components (`MTTRStatTile`, `AccuracyMeter`, `ConfidenceBucketChart`, `ResolutionFunnelChart`) can live inline in this same file (this page is not huge) or as separate files under `client/src/components/` (`MTTRStatTile.jsx`, `AccuracyMeter.jsx`, `ConfidenceBucketChart.jsx`, `ResolutionFunnelChart.jsx`) mirroring the `AlertTrendChart.jsx`/`TopAlertZonesChart.jsx` precedent of one chart per file. **Recommend the separate-files approach** since it matches the existing convention exactly and keeps each accessible-chart's `role="img"`/`aria-label`/`sr-only table` self-contained and independently testable.

