const fmToken = jwt.sign({ id: 1, role: "FM" }, process.env.APP_SECRET);

const makeIncidentInstance = (overrides = {}) => ({
  id: 1,
  resolutionStatus: "Active",
  severity: "Medium",
  person_name: null,
  notes: "",
