  destroy: jest.fn().mockResolvedValue(),
  ...overrides,
});

const makeAlertInstance = (overrides = {}) => ({
  id: 9,
  incident_log_id: 1,
  status: "Active",
  update: jest.fn().mockResolvedValue(),
  destroy: jest.fn().mockResolvedValue(),
  ...overrides,
});

