/* --- Source split bar (Manual / Facial Recognition / Object Detection) ---
   Colors are intentionally NOT the same as the table's .inc-source-fr/-od/-manual
   badges above — this triplet (#3987e5/#d95926/#199e70) was chosen and validated
   for colorblind-safe adjacent-pair separation specifically for this bar+legend;
   the older badge triplet fails that check. Same 3 categories, different (better)
   hues — not a bug. */
.inc-source-splitbar-wrap {
  margin-bottom: 16px;
}

.inc-source-splitbar {
  display: flex;
  height: 12px;
  border-radius: 4px;
  overflow: hidden;
  background: #2d364f;
}

.inc-source-segment {
  height: 100%;
  transition: filter 0.15s;
}

.inc-source-segment + .inc-source-segment {
  margin-left: 2px;
}

.inc-source-segment:hover,
.inc-source-segment:focus-visible {
  filter: brightness(1.15);
  outline: none;
}

.inc-source-seg-manual { background: #199e70; }
.inc-source-seg-fr     { background: #3987e5; }
.inc-source-seg-od     { background: #d95926; }
.inc-source-seg-empty  { background: #2d364f; }

.inc-source-legend {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 8px;
}

.inc-source-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #94a3b8;
  font-size: 0.78rem;
}

.inc-source-legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.inc-source-legend-dot-manual { background: #199e70; }
.inc-source-legend-dot-fr     { background: #3987e5; }
.inc-source-legend-dot-od     { background: #d95926; }

