const { chromium } = require('playwright');

const BASE = 'http://localhost:5174';
const FM_TOKEN = process.env.FM_TOKEN;
const STAFF_TOKEN = process.env.STAFF_TOKEN;

const consoleErrors = [];

(async () => {
  const browser = await chromium.launch({ channel: 'msedge' });
  const context = await browser.newContext();
  await context.addInitScript(([token]) => {
    localStorage.setItem('accessToken', token);
    localStorage.setItem('userRole', 'FM');
    localStorage.setItem('userName', 'Admin FM');
    localStorage.setItem('userId', '1');
  }, [FM_TOKEN]);

  const page = await context.newPage();
  page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(`[incidents] ${msg.text()}`); });
  page.on('pageerror', (err) => consoleErrors.push(`[incidents pageerror] ${err.message}`));

  await page.goto(`${BASE}/incidents`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  await page.screenshot({ path: 'shot-1-incidents-before.png', fullPage: true });

  // Legend text before any changes
  const legendBefore = await page.locator('.inc-source-legend').innerText().catch(() => 'MISSING');
  console.log('LEGEND BEFORE:', legendBefore);

  // Create a Manual incident
  await page.click('button.inc-create-btn');
  await page.waitForTimeout(300);
  await page.fill('input[name="camera_location"], #camera_location, input[placeholder*="Location" i]', 'Verify Loading Bay').catch(async () => {
    // fallback: find the first text input in the create modal
    const inputs = await page.locator('.modal-content input[type="text"], .inc-create-modal input[type="text"]').all();
    if (inputs[0]) await inputs[0].fill('Verify Loading Bay');
  });
  await page.screenshot({ path: 'shot-2-create-modal.png', fullPage: true });

  await browser.close();
  console.log('CONSOLE ERRORS:', JSON.stringify(consoleErrors, null, 2));
})().catch((e) => { console.error('SCRIPT ERROR:', e); process.exit(1); });

