const { chromium } = require('playwright');

const BASE = 'http://localhost:5174';
const FM_TOKEN = process.env.FM_TOKEN;
const STAFF_TOKEN = process.env.STAFF_TOKEN;
const consoleErrors = [];

(async () => {
  const browser = await chromium.launch({ channel: 'msedge' });

  // --- FM: full analytics page ---
  const fmContext = await browser.newContext();
  await fmContext.addInitScript((token) => {
    localStorage.setItem('accessToken', token);
    localStorage.setItem('userRole', 'FM');
    localStorage.setItem('userName', 'Admin FM');
  }, FM_TOKEN);
  const fmPage = await fmContext.newPage();
  fmPage.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(`[fm page] ${msg.text()}`); });
  fmPage.on('pageerror', (err) => consoleErrors.push(`[fm pageerror] ${err.message}`));

  await fmPage.goto(`${BASE}/incidents/analytics`, { waitUntil: 'networkidle' });
  await fmPage.waitForTimeout(1000);
  await fmPage.screenshot({ path: 'shot-12-analytics-full.png', fullPage: true });

  const mttrText = await fmPage.locator('.ia-stat-tile').first().innerText();
  const accuracyText = await fmPage.locator('.ia-stat-tile').nth(1).innerText();
  console.log('MTTR TILE:', mttrText.replace(/\n/g, ' | '));
  console.log('ACCURACY TILE:', accuracyText.replace(/\n/g, ' | '));

  const funnelAside = await fmPage.locator('.ia-funnel-aside').innerText();
  console.log('FUNNEL ASIDE (False Positive):', funnelAside.replace(/\n/g, ' | '));

  // --- Staff: should be blocked from /incidents/analytics ---
  const staffContext = await browser.newContext();
  await staffContext.addInitScript((token) => {
    localStorage.setItem('accessToken', token);
    localStorage.setItem('userRole', 'Staff');
    localStorage.setItem('userName', 'Staff User');
  }, STAFF_TOKEN);
  const staffPage = await staffContext.newPage();
  await staffPage.goto(`${BASE}/incidents/analytics`, { waitUntil: 'networkidle' });
  await staffPage.waitForTimeout(800);
  console.log('STAFF URL AFTER NAV:', staffPage.url());
  const staffBodyText = (await staffPage.locator('body').innerText()).slice(0, 300);
  console.log('STAFF PAGE TEXT SNIPPET:', staffBodyText.replace(/\n/g, ' | '));
  await staffPage.screenshot({ path: 'shot-13-staff-blocked.png', fullPage: true });

  console.log('CONSOLE ERRORS:', JSON.stringify(consoleErrors, null, 2));
  await browser.close();
})().catch((e) => { console.error('SCRIPT ERROR:', e); process.exit(1); });

