const { chromium } = require('playwright');

const BASE = 'http://localhost:5175';
const FM_TOKEN = process.env.FM_TOKEN;
const consoleErrors = [];

(async () => {
  const browser = await chromium.launch({ channel: 'msedge' });
  const context = await browser.newContext();
  await context.addInitScript((token) => {
    localStorage.setItem('accessToken', token);
    localStorage.setItem('userRole', 'FM');
    localStorage.setItem('userName', 'Admin FM');
  }, FM_TOKEN);

  const page = await context.newPage();
  page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(`[page] ${msg.text()}`); });
  page.on('pageerror', (err) => consoleErrors.push(`[pageerror] ${err.message}`));

  await page.goto(`${BASE}/incidents`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);
  await page.screenshot({ path: 'shot-escalate-1-row-buttons.png', fullPage: false });

  const row = page.locator('table.inc-table tbody tr').first();
  await row.locator('button:has-text("Escalate to Ticket")').click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'shot-escalate-2-modal.png', fullPage: true });

  await page.click('button:has-text("Confirm Escalation")');
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'shot-escalate-3-toast.png', fullPage: true });

  console.log('CONSOLE ERRORS:', JSON.stringify(consoleErrors, null, 2));
  await browser.close();
})().catch((e) => { console.error('SCRIPT ERROR:', e); process.exit(1); });

