2	import { useEffect, useLayoutEffect, useRef, useState } from 'react';
3	import { NavLink, useNavigate } from 'react-router';
4	import LogoIcon from './LogoIcon';
5	import { ROLES, roleLabel } from '../constants/roles';
6	
7	export const SIDEBAR_SCROLL_STORAGE_KEY = 'flowguard_sidebar_scroll';
8	
9	const Sidebar = () => {
10	  const navigate = useNavigate();
11	  const navRef = useRef(null);
12	  const [user] = useState(() => {
13	    const storedName = localStorage.getItem("userName");
14	    const storedRole = localStorage.getItem("userRole");
15	    return storedName && storedRole
16	      ? { name: storedName, role: storedRole }
17	      : { name: 'Guest', role: ROLES.TENANT };
18	  });
19	  const [isOpen, setIsOpen] = useState(false);
20	
21	  useLayoutEffect(() => {
22	    const nav = navRef.current;
23	    if (!nav) return undefined;
24	
25	    const restoreScroll = () => {
26	      const stored = Number(sessionStorage.getItem(SIDEBAR_SCROLL_STORAGE_KEY) || 0);
27	      if (Number.isFinite(stored) && stored > 0) {
28	        nav.scrollTop = stored;
29	      }
30	    };
31	
32	    // Restore BEFORE the browser paints so the active item never flashes at
33	    // the top; the rAF reapply is only a fallback for late layout/CSS shifts.
34	    restoreScroll();
35	    const frame = requestAnimationFrame(restoreScroll);
36	
37	    const saveScroll = () => {
38	      sessionStorage.setItem(SIDEBAR_SCROLL_STORAGE_KEY, String(nav.scrollTop));
39	    };
40	    nav.addEventListener('scroll', saveScroll, { passive: true });
41	
42	    return () => {
43	      cancelAnimationFrame(frame);
44	      nav.removeEventListener('scroll', saveScroll);
45	      saveScroll();
46	    };
47	  }, []);
48	
49	  // While the mobile drawer is open: Escape closes it, and body scrolling is locked
50	  // so the page behind the overlay can't scroll under the user's finger. Both are
51	  // fully reverted on close/unmount so desktop (where the drawer is always "open"
52	  // visually but this state stays false) is never affected.
53	  useEffect(() => {
54	    if (!isOpen) return undefined;
55	
56	    const onKeyDown = (event) => {
57	      if (event.key === 'Escape') setIsOpen(false);
58	    };
59	    document.addEventListener('keydown', onKeyDown);
60	
61	    const previousOverflow = document.body.style.overflow;
62	    document.body.style.overflow = 'hidden';
63	
64	    return () => {
65	      document.removeEventListener('keydown', onKeyDown);
66	      document.body.style.overflow = previousOverflow;
67	    };
68	  }, [isOpen]);
69	
70	  // Visibility helpers — keep these in lock-step with the route wrappers in App.jsx
71	  // so a user never sees a link that would only bounce them to the 403 page.
72	  const isFM = user.role === ROLES.FM;
73	  const isStaff = user.role === ROLES.STAFF;
74	  const isTenant = user.role === ROLES.TENANT;
75	
76	  const handleLogout = () => {
77	    localStorage.clear();
78	    navigate('/login');
79	  };
80	
81	  // Shared NavLink click handler: persist the current sidebar scroll position
82	  // BEFORE the route change remounts the layout, then close the mobile drawer.
83	  const handleNavClick = () => {
84	    const nav = navRef.current;
85	    if (nav) {
86	      sessionStorage.setItem(SIDEBAR_SCROLL_STORAGE_KEY, String(nav.scrollTop));
87	    }
88	    setIsOpen(false);
89	  };
90	
91	  return (
92	    <>
93	      {/* 1. Hamburger Button (Hidden when sidebar is open) */}
94	      {!isOpen && (
95	        <button className="mobile-menu-btn" onClick={() => setIsOpen(true)}>
96	          ☰
97	        </button>
98	      )}
99	
100	      {/* 2. Sidebar with dynamic "open" class */}
101	      <aside className={`sidebar ${isOpen ? 'open' : ''}`}>
102	        <div className="sidebar-logo">
103	          <div className="logo-title">
104	            <LogoIcon size={28} />
105	            <h2 className="gradient-text">FlowGuard</h2>
106	          </div>
107	          
108	          <button className="close-sidebar-btn" onClick={handleNavClick}>
109	            ✕
110	          </button>
111	        </div>
112	        
113	        <nav className="sidebar-nav" ref={navRef}>
114	          {/* Everyone with a session */}
115	          <NavLink to="/dashboard" onClick={handleNavClick}>Dashboard</NavLink>
116	
117	          {/* Live monitoring / AI & security — FM only (Staff are factory workers) */}
118	          {isFM && (
119	            <>
120	              <NavLink to="/cameras" onClick={handleNavClick}>Cameras</NavLink>
121	              <NavLink to="/camera-inventory" onClick={handleNavClick}>Camera Inventory</NavLink>
122	              <NavLink to="/vpatrol" onClick={handleNavClick}>V-Patrol</NavLink>
123	              <NavLink to="/object-detection" onClick={handleNavClick}>Object Detection</NavLink>
124	              <NavLink to="/detection-settings" onClick={handleNavClick}>Detection Setup</NavLink>
125	              <NavLink to="/gate-scanner" onClick={handleNavClick}>Gate Scanner</NavLink>
126	              <NavLink to="/facial-evaluation" onClick={handleNavClick}>AI Evaluation</NavLink>
127	            </>
128	          )}
129	
130	          {/* Workforce attendance — FM + Tenant + Staff (Staff see their own records) */}
131	          {(isFM || isTenant || isStaff) && (
