39	      const query = ticketFilter === 'All' ? '' : `?status=${encodeURIComponent(ticketFilter)}`;
40	      const { data } = await axios.get(`/api/support/tickets${query}`, {
41	        headers: { Authorization: `Bearer ${TOKEN()}` }
42	      });
43	      setTickets(Array.isArray(data) ? data : []);
44	    } catch {
45	      toast('Could not load support tickets.', 'error');
46	    } finally {
47	      setTicketLoading(false);
