57	    const draft = statusDrafts[ticket.id] || {};
58	    const status = draft.status || ticket.status;
59	    const resolutionNotes = draft.resolutionNotes ?? ticket.resolutionNotes ?? '';
60	
61	    setSavingId(ticket.id);
62	    try {
63	      await axios.patch(
64	        `/api/support/tickets/${ticket.id}/status`,
65	        { status, resolutionNotes },
66	        { headers: { Authorization: `Bearer ${TOKEN()}` } }
67	      );
68	      toast(`Ticket #${ticket.id.slice(0, 8).toUpperCase()} marked "${status}".`);
69	      fetchTickets();
