71	      toast('Could not update ticket status.', 'error');
72	    } finally {
73	      setSavingId(null);
74	    }
75	  };
76	
77	  const deleteTicket = async (id) => {
78	    try {
79	      await axios.delete(`/api/support/tickets/${id}`, {
80	        headers: { Authorization: `Bearer ${TOKEN()}` }
81	      });
82	      toast('Ticket and linked transcript deleted.');
83	      setDeleteConfirm(null);
84	      fetchTickets();
85	    } catch {
86	      toast('Could not delete ticket.', 'error');
87	    }
88	  };
89	
