199	                            value={draft.status ?? t.status}
200	                            onChange={e => setDraft(t.id, 'status', e.target.value)}
201	                            style={{ padding: '6px', borderRadius: '6px', background: '#1e293b', color: '#e2e8f0', border: '1px solid #334155', marginBottom: '4px', display: 'block' }}
