  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.sup-stat-card {
  background: #1e2539;
  border: 1px solid #2d364f;
  border-radius: 12px;
  padding: 22px 24px;
  transition: transform 0.2s, border-color 0.2s;
}

.sup-stat-card:hover {
  transform: translateY(-2px);
  border-color: #334155;
}

.sup-stat-blue   { border-left: 4px solid #3b82f6; }
.sup-stat-red    { border-left: 4px solid #f87171; }
.sup-stat-orange { border-left: 4px solid #f59e0b; }
.sup-stat-green  { border-left: 4px solid #34d399; }

.sup-stat-value {
  font-size: 2.2rem;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1;
  margin-bottom: 6px;
}

.sup-stat-blue   .sup-stat-value { color: #60a5fa; }
.sup-stat-red    .sup-stat-value { color: #f87171; }
.sup-stat-orange .sup-stat-value { color: #f59e0b; }
.sup-stat-green  .sup-stat-value { color: #34d399; }

.sup-stat-label {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  color: #64748b;
}

@media (max-width: 1024px) {
  .sup-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

