const { chromium } = require('playwright');

const BASE = 'http://localhost:5173';
const FM_TOKEN = process.env.FM_TOKEN;
const consoleErrors = [];

(async () => {
  const browser = await chromium.launch({ channel: 'msedge' });
  const context = await browser.newContext();
  await context.addInitScript((token) => {
    localStorage.setItem('accessToken', token);
    localStorage.setItem('userRole', 'FM');
    localStorage.setItem('userName', 'Admin FM');
  }, FM_TOKEN);

  const page = await context.newPage();
  page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(`[${page.url()}] ${msg.text()}`); });
  page.on('pageerror', (err) => consoleErrors.push(`[pageerror ${page.url()}] ${err.message}`));

  // 1. Sidebar on /dashboard
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'shot-nav-1-sidebar.png', fullPage: false });

  const sidebarText = await page.locator('nav.sidebar-nav').innerText();
  console.log('SIDEBAR LINKS:\n' + sidebarText);

  // 2. Click "Incidents & Support"
  await page.click('a:has-text("Incidents & Support")');
  await page.waitForTimeout(600);
  console.log('URL after "Incidents & Support" click:', page.url());
  await page.screenshot({ path: 'shot-nav-2-incidents-page.png', fullPage: false });

  // 3. Click "Support Tickets ->" button
  await page.click('button:has-text("Support Tickets")');
  await page.waitForTimeout(600);
  console.log('URL after "Support Tickets ->" click:', page.url());
  await page.screenshot({ path: 'shot-nav-3-support-tickets-page.png', fullPage: true });

  // 4. Navigate to Knowledge Base via sidebar
  await page.click('a:has-text("Knowledge Base")');
  await page.waitForTimeout(600);
  console.log('URL after "Knowledge Base" click:', page.url());
  await page.screenshot({ path: 'shot-nav-4-knowledge-base-page.png', fullPage: true });

  console.log('CONSOLE ERRORS:', JSON.stringify(consoleErrors, null, 2));
  await browser.close();
})().catch((e) => { console.error('SCRIPT ERROR:', e); process.exit(1); });

